package vn.edu.hunre.nhom11.carrental.payment.service;
import java.math.BigDecimal;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import vn.edu.hunre.nhom11.carrental.booking.service.BookingService;import vn.edu.hunre.nhom11.carrental.payment.domain.Payment;import vn.edu.hunre.nhom11.carrental.payment.repository.PaymentRepository;import vn.edu.hunre.nhom11.carrental.shared.exception.ApiException;
@Service public class PaymentService{private final PaymentRepository payments;private final BookingService bookings;public PaymentService(PaymentRepository p,BookingService b){payments=p;bookings=b;}@Transactional public Payment pay(String email,boolean admin,PaymentCommand r){var b=bookings.get(r.bookingId());if(!admin&&!b.getCustomer().getEmail().equalsIgnoreCase(email))throw new ApiException(HttpStatus.FORBIDDEN,"Bạn không thể thanh toán đơn này");if(b.getStatus().name().equals("CANCELLED")||b.getStatus().name().equals("COMPLETED"))throw new ApiException(HttpStatus.CONFLICT,"Đơn đã kết thúc, không thể thanh toán");if(r.amount()==null||r.amount().signum()<=0||b.getPaidAmount().add(r.amount()).compareTo(b.getTotalAmount())>0)throw new ApiException(HttpStatus.BAD_REQUEST,"Số tiền thanh toán không hợp lệ");if(blank(r.payerName())||blank(r.payerEmail())||blank(r.payerPhone())||blank(r.billingAddress())||r.method()==null)throw new ApiException(HttpStatus.BAD_REQUEST,"Vui lòng điền đầy đủ thông tin thanh toán");Payment p=new Payment();p.setBooking(b);p.setAmount(r.amount());p.setMethod(r.method());p.setPayerName(r.payerName().trim());p.setPayerEmail(r.payerEmail().trim());p.setPayerPhone(r.payerPhone().trim());p.setBillingAddress(r.billingAddress().trim());p.setProvider(r.provider());p.setNote(r.note());p.setTransactionCode("TX-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());b.setPaidAmount(b.getPaidAmount().add(r.amount()));return payments.save(p);}public Object byBooking(Long id,String email,boolean admin){var b=bookings.get(id);if(!admin&&!b.getCustomer().getEmail().equalsIgnoreCase(email))throw new ApiException(HttpStatus.FORBIDDEN,"Bạn không thể xem giao dịch của đơn này");return payments.findByBookingId(id);}public Object all(){return payments.findAll();}private boolean blank(String v){return v==null||v.isBlank();}public record PaymentCommand(Long bookingId,BigDecimal amount,Payment.Method method,String payerName,String payerEmail,String payerPhone,String billingAddress,String provider,String note){}}
